% This scrips will load all the required parameters for the two-filament% model.  % Simulation duration, time-step, and averaging parameters:%maxt = 0.1;		    %  max time for simultion (in seconds)nsteps = 1000;		%  number of time stepsdt = maxt/nsteps;	%  time step durationnruns = 25;         %  number of runs (i.e. how many times to repeat this                    %  embarasingly parallel process to get some averaging                    %  to show our output in a somewhat coherent fashion.% Data related to matrix variables and structure, such as numbers of % cross-bridges and binding sites, lattice stiffness%nXB = 20;   		%  Number of cross-bridges (default here 20)nBS = 30;   		%  Number of binding sites (default here 30)NN = nXB+nBS;       %  Total Number of cross-bridges and binding siteskamult = 1.0;       %  Spring Constant Multiplier (if needed) for the actin                    %  (i.e. thin filament) spring constant.                    kmmult = 1.0;       %  Spring constant multiplier for thick filament                    %  backbone stiffness (if needed).                    km = kmmult*2020.0;	%  Spring constant for thick filament (pN/nm, default 2020)ka = kamult*1743.0;	%  Spring constant for thin filament (pN/nm, default 1743)kms = km/6.0;		%  Spring constant for bare zone of thick filament (I think)                     %  --- Anita, you may be happy to learn that once we had this                    %  in, but somehow we lost it along the way ---                    %  default (6 times as stiff as the thick filament backbone, xb dist)                    %  Not sure this default makes sense?kas = 220.0;	    %  Spring consant for series thin filament                    %  (NOT SURE WHY THIS IS HERE--NOT SURE IT IS REQUIRED                    %  NOT THE UTILITY OF IT IN THE MODEL, BCWT APRIL 2017)                    %  It is being used as a boundary condition for the end                    %  of the thin filament, but I'm having trouble                    %  understanding why, and it is roughly 1/10 as stiff.myspace = 42.9;		%   spacing between colinear cross-bridges sites (in nm, at rest)acspace = 37.3;		%   spacing between colinear actin sites (in nm, at rest)ovlp = 2.2;			%   sarcomere length (in microns)%   BCWT--April 2017--here for y0 and below for xo; these have to do with%   boundary conditions and the force balance.  These numbers aren't making%   total sense to me, and I may have to review my notes on the boundary%   conditionsyo = 2.0*myspace;   % This sets the length of the bare zone where there is no XB for binding, and y0 effectively% becomes the distance from the M-line, where node 1 for myosin is placed% (hence sets part of the boundary condition vector)xo = ovlp*1000.0/2.0 - nBS*acspace; % In a strange way, this sort of sets the overlap, where x0 becomes the position of the z-line% even though in later versions we did this differently. Here, % xo = half-sarcomere length minus thin-filament length% (hence will set part of the boundary condition vector)% Below parameters are related to cross-bridge spring constants,% free-energies, and translating between pN/nm and RT, etc.% Most of this is used to outline the chemomechanical.  Some of these% parameters, I've spent a lot of time clarifying and revising in other% iterations of the model, so we can explore this in the future as needed.kRT = 0.2; 			%  cross bridge spring constant in RT'sRTnm2 = 4.14;       %  conversion of RT per nm squred -- perhaps pN per energy stored per nm^2 distorsion as Energy = k(delta x)^2k2 = kRT*RTnm2;     %   bridgenrg = 46.61;  % Energy stored in the XB upon ATP hydrolysis (I think)reach = sqrt(bridgenrg/k2); % XB distortionphos = 0.003;		%  Intracellular Pi